/**
 * @returns {Promise.<void>}
 */
export async function JS_ToggleScrollButton() {
	// BEGIN USER CODE
  // Prevent multiple initializations
  if (window.chatScrollButtonInitialized) {
    console.debug('Chat scroll button already initialized');
    return;
  }
  window.chatScrollButtonInitialized = true;

  // Track initialized scroll containers to prevent duplicate event listeners
  const initializedScrollContainers = new WeakSet();

  // Single source of truth: calculate and set CSS variables for all visible containers
  const updateAllVisibleContainers = () => {
    document.querySelectorAll('.chat-input-wrapper').forEach(wrapper => {
      const rect = wrapper.getBoundingClientRect();

      // Only update visible containers
      if (rect.width === 0 || rect.height === 0) return;

      const container = wrapper.closest('.chat-container, .chat-container--center, .chat-container-agent');
      if (!container) return;

      // Vertical: distance from viewport bottom to TOP of input
      const distanceFromBottom = window.innerHeight - rect.top;
      container.style.setProperty('--chat-input-height', `${distanceFromBottom}px`);

      // Horizontal: center position of chat container
      const chatRect = container.getBoundingClientRect();
      const centerX = chatRect.left + (chatRect.width / 2);
      container.style.setProperty('--chat-center-x', `${centerX}px`);
    });
  };

  // Initialize scroll position tracking for messages containers
  const initScrollTracking = (container) => {
    if (initializedScrollContainers.has(container)) return;
    initializedScrollContainers.add(container);

    const checkScrollPosition = () => {
      const isAtBottom = container.scrollTop + container.clientHeight >= container.scrollHeight - 100;

      if (isAtBottom) {
        container.classList.remove('not-at-bottom');
      } else {
        container.classList.add('not-at-bottom');
      }
    };

    checkScrollPosition();
    container.addEventListener('scroll', checkScrollPosition);
  };

  // Scan and initialize all current elements
  const scanAndInit = () => {
    document.querySelectorAll('.messages-container').forEach(initScrollTracking);
    updateAllVisibleContainers();
  };

  // Debounced update for navigation events
  let updateTimer = null;
  const debouncedUpdate = () => {
    clearTimeout(updateTimer);
    updateTimer = setTimeout(updateAllVisibleContainers, 100);
  };

  // Event listeners - all trigger the same update function
  window.addEventListener('resize', updateAllVisibleContainers);
  window.addEventListener('popstate', debouncedUpdate); // Browser back/forward
  window.addEventListener('hashchange', debouncedUpdate); // Hash navigation

  document.addEventListener('visibilitychange', () => {
    if (!document.hidden) debouncedUpdate();
  });

  // Watch for new elements (layout switches, dynamic content)
  const observer = new MutationObserver((mutations) => {
    let shouldUpdate = false;

    for (const mutation of mutations) {
      for (const node of mutation.addedNodes) {
        if (node.nodeType !== Node.ELEMENT_NODE) continue;

        // Initialize scroll tracking for new messages containers
        if (node.matches && node.matches('.messages-container')) {
          initScrollTracking(node);
        }
        if (node.querySelectorAll) {
          node.querySelectorAll('.messages-container').forEach(initScrollTracking);
        }

        // Mark that we need to update positioning
        if (node.matches && (node.matches('.chat-input-wrapper') || node.matches('.chat-container'))) {
          shouldUpdate = true;
        }
        if (node.querySelectorAll && (node.querySelectorAll('.chat-input-wrapper').length > 0)) {
          shouldUpdate = true;
        }
      }
    }

    if (shouldUpdate) debouncedUpdate();
  });

  observer.observe(document.body, {
    childList: true,
    subtree: true
  });

  // Initial setup
  scanAndInit();

  // Backup check after render settles
  setTimeout(updateAllVisibleContainers, 300);

  console.debug('Chat scroll button monitoring active');
	// END USER CODE
}
